// Stage 5.2.2 — Threshold logic: 30/15/7 day checks; classify risk level
const now = new Date();
const bgs = $input.all();
const alerts = [];

for (const bg of bgs) {
  const d = bg.json;
  if (d.status === 'released') continue;
  const expiry = new Date(d.expiryDate);
  const daysLeft = Math.ceil((expiry - now) / (1000 * 60 * 60 * 24));
  if (daysLeft <= 0 || daysLeft > 90) continue;

  let riskLevel = 'safe';
  let urgency = 0;
  let notifyChannel = 'firestore';
  if (daysLeft <= 7) { riskLevel = 'critical'; urgency = 3; notifyChannel = 'email+push+firestore'; }
  else if (daysLeft <= 15) { riskLevel = 'high'; urgency = 2; notifyChannel = 'email+firestore'; }
  else if (daysLeft <= 30) { riskLevel = 'warning'; urgency = 1; notifyChannel = 'firestore'; }

  alerts.push({
    json: {
      bgId: d.id || d.ref,
      ref: d.ref,
      projectName: d.projectName,
      projectId: d.projectId,
      amount: d.amount,
      type: d.type,
      issuingBank: d.issuingBank,
      expiryDate: d.expiryDate,
      daysLeft: daysLeft,
      riskLevel: riskLevel,
      urgency: urgency,
      notifyChannel: notifyChannel,
      alertTimestamp: now.toISOString(),
      message: `${d.ref} (${d.projectName}) expires in ${daysLeft} days. Risk: ${riskLevel.toUpperCase()}. Amount: ${d.amount}. Issuing bank: ${d.issuingBank}.`
    }
  });
}

if (alerts.length === 0) {
  return [{ json: { status: 'no_alerts', message: 'No BG expiries within 90-day horizon.', timestamp: now.toISOString() } }];
}

return alerts;

